import java.util.LinkedList;
import java.util.Queue;

public class SimpleQueueExample {
    public static void main(String[] args) {
        // Creating a simple queue
        Queue<String> queue = new LinkedList<>();

        // Enqueue items
        queue.add("First");
        queue.add("Second");
        queue.add("Third");

        // Dequeue items
        System.out.println(queue.poll());  // Output: First
        System.out.println(queue.poll());  // Output: Second
    }
}

public class CircularQueueExample {
    static class CircularQueue {
        int[] queue;
        int front, rear, size;
        int capacity;

        CircularQueue(int capacity) {
            this.capacity = capacity;
            queue = new int[capacity];
            front = 0;
            rear = -1;
            size = 0;
        }

        // Enqueue operation
        public void enqueue(int data) {
            if (size == capacity) {
                System.out.println("Queue is full");
            } else {
                rear = (rear + 1) % capacity;
                queue[rear] = data;
                size++;
            }
        }

        // Dequeue operation
        public int dequeue() {
            if (size == 0) {
                System.out.println("Queue is empty");
                return -1;
            } else {
                int item = queue[front];
                front = (front + 1) % capacity;
                size--;
                return item;
            }
        }
    }

    public static void main(String[] args) {
        CircularQueue cq = new CircularQueue(5);
        cq.enqueue(1);
        cq.enqueue(2);
        cq.enqueue(3);

        System.out.println(cq.dequeue());  // Output: 1
        cq.enqueue(4);

        System.out.println(cq.dequeue());  // Output: 2
    }
}

import java.util.PriorityQueue;

public class PriorityQueueExample {
    public static void main(String[] args) {
        // PriorityQueue (min-heap by default)
        PriorityQueue<Integer> pq = new PriorityQueue<>();

        // Enqueue items with different priorities
        pq.add(10);
        pq.add(5);
        pq.add(20);

        // Dequeue items (priority order)
        System.out.println(pq.poll());  // Output: 5 (smallest priority)
        System.out.println(pq.poll());  // Output: 10
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

public class DequeExample {
    public static void main(String[] args) {
        Deque<String> deque = new ArrayDeque<>();

        // Enqueue items at both ends
        deque.addFirst("First");
        deque.addLast("Second");

        // Dequeue items from both ends
        System.out.println(deque.pollFirst());  // Output: First
        System.out.println(deque.pollLast());   // Output: Second
    }
}

